"Add your licence and TIN under Settings → Documents, then submit for review. Until then you can see requests but not quote.": "ፈቃድዎንና TINዎን በቅንብሮች → ሰነዶች ስር ያክሉ፣ ከዚያ ለግምገማ ያስገቡ። እስከዚያ ድረስ ጥያቄዎችን ማየት ይችላሉ፣ ዋጋ ግን ማቅረብ አይችሉም።",
