"Adding your dispatch points helps you receive requests near you, lets you offer free or lower delivery, and helps you win orders. This information is never shown to buyers or the public. Our team will call you within {1} days to help.": "የዕቃ መጫኛ ቦታዎችዎን ማከል በአቅራቢያዎ ያሉ ጥያቄዎችን እንዲቀበሉ፣ ነፃ ወይም ዝቅተኛ የማድረሻ ዋጋ እንዲያቀርቡ እና ትዕዛዞችን እንዲያሸንፉ ይረዳዎታል። ይህ መረጃ ለገዢዎች ወይም ለሕዝብ ፈጽሞ አይታይም። ቡድናችን እርስዎን ለመርዳት በ{1} ቀናት ውስጥ ይደውልልዎታል።",
