"After confirmation the PO/SA is not edited: a change is asked for and binds only when the other party accepts it.": "ከተረጋገጠ በኋላ የግ.ት/የሽ.ስ አይስተካከልም፤ ለውጥ ይጠየቃል፣ አስገዳጅ የሚሆነው ሌላኛው ወገን ሲቀበለው ብቻ ነው።",
