"After the handover the buyer checks every item on the platform within {1} hours; a problem is reported there, with a photo where it can be seen. Items not answered within {2} hours count as received. Build Smartly mediates within one working day.": "ከርክክቡ በኋላ ገዢው እያንዳንዱን ዕቃ በመድረኩ ላይ በ{1} ሰዓት ውስጥ ይፈትሻል፤ ችግር እዚያው ይዘገባል፣ በሚታይበት ጊዜ ከፎቶ ጋር። በ{2} ሰዓት ውስጥ ያልተመለሱ ዕቃዎች እንደደረሱ ይቆጠራሉ። Build Smartly በአንድ የሥራ ቀን ውስጥ ያስታርቃል።",
"Agents for Mugher and National cement. Bulk and bagged, sub-city depots in Kirkos and Nifas Silk.": "የMugher እና የNational ሲሚንቶ ወኪሎች። በጅምላና በከረጢት፤ በKirkos እና በNifas Silk ክፍለ ከተሞች መጋዘኖች አሉን።",
