"Brands, suppliers and contractors can advertise: a banner in the slideshow and an item in the monthly newsletter that goes to every member. Send your news from the Newsletter page; staff check it and finance sends the invoice.": "ብራንዶች፣ አቅራቢዎችና ኮንትራክተሮች ማስታወቂያ ማውጣት ይችላሉ፦ በተንሸራታች ምስሎቹ ውስጥ ባነር እና ለሁሉም አባላት በሚላከው ወርሃዊ ዜና መጽሔት ውስጥ ጽሑፍ። ዜናዎን ከዜና መጽሔት ገጹ ይላኩ፤ ሠራተኞች ያጣሩታል፣ የፋይናንስ ክፍሉም ደረሰኝ ይልካል።",
