"Build Smartly S.C. is an Ethiopian share company. Its shareholders are contractors, engineers, suppliers and investors who have all bought materials the hard way: many phone calls, prices that change by the day, and no record of what was agreed.": "Build Smartly S.C. የኢትዮጵያ አክሲዮን ማኅበር ነው። ባለአክሲዮኖቹ ኮንትራክተሮች፣ መሐንዲሶች፣ አቅራቢዎችና ባለሀብቶች ሲሆኑ ሁሉም ዕቃዎችን በአስቸጋሪው መንገድ የገዙ ናቸው፦ ብዙ የስልክ ጥሪዎች፣ በየቀኑ የሚለዋወጡ ዋጋዎች፣ እና የተስማሙበትን ነገር የሚያሳይ መዝገብ አለመኖር።",
