"Build Smartly cancelled this PO/SA.": "Build Smartly ይህን የግ.ት/የሽ.ስ ሰርዞታል።",
"Build Smartly cancelled this PO/SA. Choose another offer.": "Build Smartly ይህን የግ.ት/የሽ.ስ ሰርዞታል። ሌላ ዋጋ ይምረጡ።",
