"Build Smartly in numbers": "Build Smartly በቁጥሮች",
"Build Smartly in pictures": "Build Smartly በምስሎች",
"Build Smartly is a platform that connects verified buyers and suppliers of construction materials and equipment. The sale contract is between the buyer and the supplier. Build Smartly issues the purchase order and contract documents and records the deal.": "Build Smartly የተረጋገጡ የግንባታ ዕቃዎችና መሣሪያዎች ገዢዎችንና አቅራቢዎችን የሚያገናኝ መድረክ ነው። የሽያጭ ውሉ በገዢውና በአቅራቢው መካከል ነው። Build Smartly የግዢ ትዕዛዝና የውል ሰነዶችን ያወጣል፣ ስምምነቱንም ይመዘግባል።",
"Build Smartly is a platform that connects verified buyers and suppliers of construction materials and equipment. The sale is between the buyer and the supplier; Build Smartly facilitates it and is not a party to it. Build Smartly issues the Purchase Order / Sales Agreement and records the deal.": "Build Smartly የተረጋገጡ የግንባታ ዕቃዎችና መሣሪያዎች ገዢዎችንና አቅራቢዎችን የሚያገናኝ መድረክ ነው። ሽያጩ በገዢውና በአቅራቢው መካከል ነው፤ Build Smartly ያመቻቻል እንጂ ተዋዋይ ወገን አይደለም። Build Smartly የግዢ ትዕዛዝ / የሽያጭ ስምምነቱን ያወጣል፣ ስምምነቱንም ይመዘግባል።",
"Build Smartly is the working name. Everything works, but no SMS is sent and no money moves. One buyer, two suppliers and two staff logins.": "Build Smartly የሥራ ስም ነው። ሁሉም ነገር ይሠራል፣ ነገር ግን ምንም SMS አይላክም፣ ምንም ገንዘብም አይንቀሳቀስም። አንድ ገዢ፣ ሁለት አቅራቢዎችና ሁለት የሠራተኛ መግቢያዎች።",
"Build Smartly logo": "የBuild Smartly አርማ",
"Build Smartly operations": "የBuild Smartly ሥራ አመራር",
"Build Smartly prototype review": "የBuild Smartly የሙከራ ድረ-ገጽ ግምገማ",
"Build Smartly sends a newsletter to all registered members: a link by SMS, Telegram and e-mail. Brands, suppliers and contractors can all advertise: a banner with your picture in the slideshow on the home page and in every member's workspace, and an item in the newsletter. A verified profile in the Members directory is free. Sponsored places are always marked and never change the order of offers a buyer sees. Prices are examples; the owner sets the final rates.": "Build Smartly ለሁሉም የተመዘገቡ አባላት ጋዜጣ ይልካል፦ ሊንኩ በSMS፣ በTelegram እና በኢ-ሜይል ይደርሳል። ብራንዶች፣ አቅራቢዎችና ኮንትራክተሮች ሁሉም ማስታወቂያ ማውጣት ይችላሉ፦ በመነሻ ገጹና በእያንዳንዱ አባል የሥራ ገጽ ላይ በተንሸራታች ምስሎቹ ውስጥ ምስልዎን የያዘ ባነር፣ እና በጋዜጣው ውስጥ ጽሑፍ። በአባላት ማውጫ ውስጥ የተረጋገጠ መግለጫ በነፃ ነው። በስፖንሰር የቀረቡ ቦታዎች ሁልጊዜ ምልክት ይደረግባቸዋል፣ ገዢው የሚያየውን የቅናሾች ቅደም ተከተልም ፈጽሞ አይቀይሩም። ዋጋዎቹ ምሳሌ ናቸው፤ የመጨረሻውን ተመን ባለቤቱ ይወስናል።",
"Build Smartly sends you the account details by SMS.": "Build Smartly የሂሳብ ዝርዝሩን በኤስኤምኤስ ይልክልዎታል።",
"Build Smartly staff": "የBuild Smartly ሠራተኞች",
"Build Smartly staff have put your account on hold for review. You cannot quote until staff make it active again. Write to support if you have a question.": "የBuild Smartly ሠራተኞች መለያዎን ለግምገማ አቁመውታል። ሠራተኞች መልሰው እስኪያነቁት ድረስ ዋጋ ማቅረብ አይችሉም። ጥያቄ ካለዎት ለድጋፍ ይጻፉ።",
"Build Smartly staff sign-in": "የBuild Smartly ሠራተኞች መግቢያ",
"Build Smartly staff:": "የBuild Smartly ሠራተኞች፦",
"Build Smartly support": "የBuild Smartly ድጋፍ",
"Build Smartly support · {1}/{2}/{3} {4}:{5}:{6} PM": "የBuild Smartly ድጋፍ · {1}/{2}/{3} {4}:{5}:{6} ከሰዓት",
"Build Smartly · October {1}": "Build Smartly · ኦክቶበር {1}",
"Build Smartly: send your BOQ, get real supplier quotes, choose line by line": "Build Smartly፦ BOQዎን ይላኩ፣ ከአቅራቢዎች እውነተኛ ዋጋ ያግኙ፣ በየመስመሩ ይምረጡ",
"Build Smartly: we received your list (request BS-{1}-{2}). Our team types it in and sends it to suppliers. We will text you when it has gone out.": "Build Smartly፦ ዝርዝርዎ ደርሶናል (ጥያቄ BS-{1}-{2})። ቡድናችን አስገብቶ ለአቅራቢዎች ይልካል። ሲላክ በጽሑፍ መልዕክት እናሳውቅዎታለን።",
"Build Smartly: we received your request BS-{1}-{2} ({3} items). Suppliers have {4} days. We will text you when the first offer is ready.": "Build Smartly፦ ጥያቄዎ BS-{1}-{2} ({3} ዕቃዎች) ደርሶናል። አቅራቢዎች {4} ቀናት አላቸው። የመጀመሪያው ቅናሽ ሲደርስ በመልዕክት እናሳውቅዎታለን።",
"Build Smartly: we received your request BS-{1}-{2}. Our team checks it and sends it to suppliers. We will text you when it has gone out.": "Build Smartly፦ ጥያቄዎ BS-{1}-{2} ደርሶናል። ቡድናችን መርምሮ ለአቅራቢዎች ይልካል። ሲላክ በጽሑፍ መልዕክት እናሳውቅዎታለን።",
"Build a list or upload your BOQ": "ዝርዝር ያዘጋጁ ወይም የBOQ ፋይልዎን ያስገቡ",
"Build your list first. You sign in when you send it.": "መጀመሪያ ዝርዝርዎን ያዘጋጁ። የሚገቡት ሲልኩት ነው።",
