"Buyers and suppliers keep full authority over every commercial decision they make.": "ገዢዎችና አቅራቢዎች በሚወስኑት እያንዳንዱ የንግድ ውሳኔ ላይ ሙሉ ሥልጣን ይኖራቸዋል።",
"Buyers need only a name and a mobile number. Company details and TIN come later, before your first purchase order. Suppliers register their company, TIN and a password.": "ገዢዎች የሚያስፈልጋቸው ስምና የሞባይል ቁጥር ብቻ ነው። የድርጅት ዝርዝርና TIN በኋላ፣ ከመጀመሪያው የግዢ ትዕዛዝዎ በፊት ይጠየቃሉ። አቅራቢዎች ድርጅታቸውን፣ TIN እና የይለፍ ቃል ያስመዘግባሉ።",
"Buyers send their Fayda number, or TIN and business licence, or an official letter.": "ገዢዎች የፋይዳ ቁጥራቸውን፣ ወይም የግብር ከፋይ ቁጥርና የንግድ ፈቃድ፣ ወይም ይፋዊ ደብዳቤ ይልካሉ።",
"Buyers sign in with their mobile number and the SMS code (on the test site the code is {1}). Suppliers use the supplier sign-in with number and password. One number can be both a buyer and a supplier.": "ገዢዎች በሞባይል ቁጥራቸውና በSMS ኮድ ይገባሉ (በሙከራ ድረ-ገጹ ላይ ኮዱ {1} ነው)። አቅራቢዎች በቁጥርና በይለፍ ቃል በአቅራቢ መግቢያ ይገባሉ። አንድ ቁጥር ገዢም አቅራቢም ሊሆን ይችላል።",
"Buyers to verify": "የሚረጋገጡ ገዢዎች",
"Buyers: your name or company name and TIN, asked once when you accept your first offer, so the purchase order can be issued. A person without a TIN shows a Fayda ID to staff instead. A government office gives an official authorisation letter. Suppliers: business licence and TIN certificate before the first quote. Nothing is needed to open the account or to send a request.": "ገዢዎች፦ ስምዎ ወይም የድርጅትዎ ስምና TIN፣ የግዢ ትዕዛዙ እንዲወጣ የመጀመሪያ ቅናሽዎን ሲቀበሉ አንድ ጊዜ ይጠየቃሉ። TIN የሌለው ግለሰብ በምትኩ የፋይዳ መታወቂያውን ለሠራተኞች ያሳያል። የመንግሥት መሥሪያ ቤት ኦፊሴላዊ የውክልና ደብዳቤ ያቀርባል። አቅራቢዎች፦ ከመጀመሪያው ዋጋ ማቅረብ በፊት የንግድ ፈቃድና የTIN ሰርተፊኬት። መለያ ለመክፈት ወይም ጥያቄ ለመላክ ምንም አያስፈልግም።",
