"Choose a main category (first tap) and up to five more. Requests are sent to you only for these.": "ዋና ዘርፍ (የመጀመሪያ መንካት) እና እስከ አምስት ተጨማሪ ይምረጡ። ጥያቄዎች የሚላኩልዎ ለእነዚህ ብቻ ነው።",
