"Dispatched, but the tracking link could not be made. The buyer confirms the delivery with the code.": "ተልኳል፣ ግን የክትትል ሊንኩ መፍጠር አልተቻለም። ገዢው መድረሱን በኮዱ ያረጋግጣል።",
"Dispatched. At the site the buyer checks the goods and gives the driver the {1}-digit handover code; the buyer then confirms the delivery.": "ተልኳል። ቦታው ላይ ገዢው ዕቃውን ፈትሾ ለሾፌሩ ባለ {1} አሃዝ የርክክብ ኮዱን ይሰጣል፤ ከዚያም ገዢው መድረሱን ያረጋግጣል።",
"Dispatched. At the site the buyer checks the goods and gives the driver the {1}-digit handover code; the buyer types the code printed on the delivery note.": "ተልኳል። ቦታው ላይ ገዢው ዕቃውን ፈትሾ ለሾፌሩ ባለ {1} አሃዝ የርክክብ ኮዱን ይሰጣል፤ ገዢው በማድረሻ ማስታወሻው ላይ የታተመውን ኮድ ያስገባል።",
"Dispatched. Print the delivery note for the driver.": "ተልኳል። ለሾፌሩ የማድረሻ ማስታወሻውን ያትሙ።",
"Dispatched. Send the link to the driver; the buyer got the handover code.": "ተልኳል። ሊንኩን ለሾፌሩ ይላኩ፤ ገዢው የርክክብ ኮዱን አግኝቷል።",
"Dispatched. Send the tracking link below to the driver. At the site the buyer checks the goods and gives the driver the {1}-digit handover code; the driver types it on the tracking page and the order is marked delivered.": "ተልኳል። ከታች ያለውን የክትትል ሊንክ ለሾፌሩ ይላኩ። ቦታው ላይ ገዢው ዕቃውን ፈትሾ ለሾፌሩ ባለ {1} አሃዝ የርክክብ ኮዱን ይሰጣል፤ ሾፌሩ በክትትል ገጹ ላይ ያስገባዋል፣ ትዕዛዙም እንደደረሰ ይመዘገባል።",
"Dispatched. Send the tracking link below to the driver. At the site the buyer checks the goods and gives the driver the {1}-digit handover code; the driver types it on the tracking page. If the driver's phone fails, the buyer types the code on the delivery note instead.": "ተልኳል። ከታች ያለውን የክትትል ሊንክ ለሾፌሩ ይላኩ። ቦታው ላይ ገዢው ዕቃውን ፈትሾ ለሾፌሩ ባለ {1} አሃዝ የርክክብ ኮዱን ይሰጣል፤ ሾፌሩ በክትትል ገጹ ላይ ያስገባዋል። የሾፌሩ ስልክ ካልሰራ ገዢው በማድረሻ ማስታወሻው ላይ ያለውን ኮድ ያስገባል።",
"Dispatched. The buyer got the handover code.": "ተልኳል። ገዢው የርክክብ ኮዱን አግኝቷል።",
