"Each offer shows its payment terms, set by the supplier: full payment before dispatch, a deposit with the balance after delivery, full payment after delivery, or credit (pay within a number of days of delivery). The terms become part of the PO/SA. You pay on the order page when a payment is due: Telebirr, CBE Birr or a card through the Yagout Pay gateway, or a bank transfer to Build Smartly. The receipt is ready at once, under Documents and in your Statements.": "እያንዳንዱ ዋጋ በአቅራቢው የተወሰነውን የክፍያ ውል ያሳያል፦ ከመላኩ በፊት ሙሉ ክፍያ፣ ቅድመ ክፍያ እና ቀሪው ከርክክብ በኋላ፣ ከርክክብ በኋላ ሙሉ ክፍያ፣ ወይም ዱቤ (ከርክክብ በኋላ በተወሰኑ ቀናት ውስጥ መክፈል)። ውሎቹ የግዢ ትዕዛዝ/ሽያጭ ስምምነቱ አካል ይሆናሉ። ክፍያ ሲደርስ በትዕዛዙ ገጽ ላይ ይከፍላሉ፦ ቴሌብር፣ ሲቢኢ ብር ወይም ካርድ በያጎውት ፔይ በኩል፣ ወይም ወደ ቢልድ ስማርትሊ በባንክ ዝውውር። ደረሰኙ ወዲያውኑ በሰነዶች እና በመግለጫዎችዎ ውስጥ ዝግጁ ነው።",
