"Everything members report on their orders, tracked until resolved. Take a case, add notes, resolve with a note; both parties see the state on the order page.": "አባላት በትዕዛዞቻቸው ላይ የሚያሳውቁት ሁሉ፣ እስኪፈታ ድረስ ክትትል ይደረግበታል። ጉዳዩን ይውሰዱ፣ ማስታወሻ ያክሉ፣ በማስታወሻ ይዝጉት፤ ሁለቱም ወገኖች ሁኔታውን በትዕዛዝ ገጹ ላይ ያያሉ።",
