"Five categories: Foundation, Structure, Electrical and plumbing, Finishing, Equipment rental. Each line of your request goes only to verified suppliers of that material. Something not in the list? Type it; staff classify it.": "አምስት ዘርፎች፦ መሠረት፣ መዋቅር፣ ኤሌክትሪክ እና ቧንቧ፣ የማጠናቀቂያ ሥራ፣ የመሣሪያ ኪራይ። እያንዳንዱ የጥያቄዎ መስመር የሚሄደው ያንን ዕቃ ለሚያቀርቡ የተረጋገጡ አቅራቢዎች ብቻ ነው። በዝርዝሩ ውስጥ የሌለ ነገር አለ? ይጻፉት፤ ሠራተኞች ይመድቡታል።",
