"Give an offer": "ቅናሽ ይስጡ",
"Give this code to the buyer when the goods are handed over. The buyer types it on the Build Smartly order page.": "ዕቃው ሲረከብ ይህን ኮድ ለገዢው ይስጡ። ገዢው በBuild Smartly የትዕዛዝ ገጽ ላይ ያስገባዋል።",
"Glass and ironmongery": "መስታወት እና ሃርድዌር",
"Go back to": "ተመለስ ወደ",
"Go through each part of the prototype, mark it Approve or Change, and write what you want adjusted. Save at the end. The same checklist is also available as a Word document if you prefer to write your comments there.": "እያንዳንዱን የናሙናውን ክፍል ይመልከቱ፣ ይጽደቅ ወይም ይቀየር ብለው ምልክት ያድርጉ፣ እና እንዲስተካከል የሚፈልጉትን ይጻፉ። በመጨረሻ ያስቀምጡ። አስተያየትዎን እዚያ መጻፍ ከመረጡ ተመሳሳዩ የማረጋገጫ ዝርዝር በWord ሰነድም ይገኛል።",
"Go to Send a request, tick the materials you need, type the quantity and the date you need them, choose the delivery site and press Send. You sign in with your mobile number and the SMS code at that moment; no form to fill. You can also download the Excel template, let your engineer fill it, and upload it.": "ወደ «ጥያቄ ይላኩ» ይሂዱ፣ የሚፈልጓቸውን ዕቃዎች ምልክት ያድርጉ፣ ብዛቱንና የሚፈልጉበትን ቀን ይጻፉ፣ የሚደርስበትን ሳይት ይምረጡና «ላክ»ን ይጫኑ። በዚያን ጊዜ በሞባይል ቁጥርዎና በSMS ኮድ ይገባሉ፤ የሚሞላ ቅጽ የለም። የExcel ቅጹን አውርደው መሐንዲስዎ እንዲሞላው ማድረግና መጫንም ይችላሉ።",
"Go to the supplier portal": "ወደ አቅራቢ ፖርታል ይሂዱ",
"Goods": "ዕቃዎች",
"Goods are handed over against the buyer's 4-digit handover code, typed by the driver, or the code on the delivery note, typed by the buyer. Hired equipment is returned on the return date as arranged between the parties.": "ዕቃዎቹ የሚረከቡት ሹፌሩ በሚያስገባው የገዢው ባለ 4 አኃዝ የማስረከቢያ ኮድ፣ ወይም ገዢው በሚያስገባው የማስረከቢያ ደብተር ኮድ ነው። የተከራዩ መሣሪያዎች በተዋዋዮቹ ስምምነት በመመለሻ ቀኑ ይመለሳሉ።",
