"Handed over. The buyer is checking each item (up to {1} hours); you see every answer below.": "ተረክቧል። ገዢው እያንዳንዱን ዕቃ እየፈተሸ ነው (እስከ {1} ሰዓት)፤ እያንዳንዱን መልስ ከታች ያያሉ።",
