"Held: the buyer is being verified by our team. You can confirm once they are; your hours start then.": "ተይዟል፦ ገዢው በቡድናችን እየተረጋገጠ ነው። ከተረጋገጠ በኋላ ማረጋገጥ ይችላሉ፤ ሰዓታትዎ ያኔ ይጀምራሉ።",
"Hello": "ሰላም",
"Hello. I am the Build Smartly assistant. Ask me how to send a request, compare offers, pay, or register as a supplier.": "ጤና ይስጥልኝ። እኔ የBuild Smartly ረዳት ነኝ። ጥያቄ እንዴት እንደሚልኩ፣ ዋጋዎችን እንዴት እንደሚያወዳድሩ፣ እንዴት እንደሚከፍሉ ወይም እንደ አቅራቢ እንዴት እንደሚመዘገቡ ይጠይቁኝ።",
