"Highlighted card in the Members directory · example ETB {1} per month": "በአባላት ማውጫ ውስጥ ጎልቶ የሚታይ ካርድ · ምሳሌ ETB {1} በወር",
"Hired equipment: the supplier brings it and collects it on the return date; you arrange it with them.": "የተከራዩ መሣሪያዎች: አቅራቢው ያመጣዋል፣ በመመለሻ ቀኑም ይወስደዋል፤ ከእነሱ ጋር ያመቻቹ።",
"History": "ታሪክ",
"History, brands, certifications, key products": "ታሪክ፣ ብራንዶች፣ የምስክር ወረቀቶች፣ ዋና ዋና ምርቶች",
"Hold ended: the buyer was not verified in time": "መያዙ አብቅቷል፦ ገዢው በጊዜው አልተረጋገጠም",
"Hollow concrete blocks, aggregates and formwork plywood from our Lemi Kura plant.": "ብሎኬት፣ ጠጠርና የቅርጽ ጣውላ ከLemi Kura ፋብሪካችን።",
"Home": "መነሻ",
"Home banner · wide photo of a site in Addis Ababa": "የመነሻ ገጽ ባነር · በአዲስ አበባ ያለ የግንባታ ሳይት ሰፊ ፎቶ",
"Home page and announcement": "መነሻ ገጽና ማስታወቂያ",
"Home page banner": "የመነሻ ገጽ ባነር",
"Home page only": "መነሻ ገጽ ብቻ",
"Home page overall": "የመነሻ ገጽ በአጠቃላይ",
