"Home, Requests, Offers and orders, Price list, Mailbox, Settings": "መነሻ፣ ጥያቄዎች፣ የዋጋ ማቅረቢያዎች እና ትዕዛዞች፣ የዋጋ ዝርዝር፣ የመልዕክት ሳጥን፣ ቅንብሮች",
"Hosted in Ethiopia under the Personal Data Protection Proclamation. Amharic, Afaan Oromoo and English.": "በግል መረጃ ጥበቃ አዋጅ መሠረት በኢትዮጵያ ውስጥ የሚስተናገድ። አማርኛ፣ አፋን ኦሮሞ እና እንግሊዝኛ።",
"Hours a driver's tracking link lasts (up to {1})": "የሾፌሩ የክትትል ሊንክ የሚቆይበት ሰዓት (እስከ {1})",
"Hours the buyer has to check the items": "ገዢው ዕቃዎቹን ለመፈተሽ ያለው ሰዓት",
"Hours the supplier has to confirm a PO/SA": "አቅራቢው የግ.ት/የሽ.ስ ለማረጋገጥ ያለው ሰዓት",
"How Build Smartly works": "Build Smartly እንዴት እንደሚሠራ",
"How a profile gets here": "መገለጫ እዚህ እንዴት እንደሚደርስ",
"How buyers pay, how deliveries are checked, and what drivers see.": "ገዢዎች እንዴት እንደሚከፍሉ፣ ማድረሻዎች እንዴት እንደሚፈተሹ እና ሾፌሮች የሚያዩትን።",
"How do I pay?": "እንዴት እከፍላለሁ?",
