"No account needed to build your list. You enter your mobile number when you send it. Fees apply only on a completed deal, as a small percentage of the order. Rate to be announced.": "ዝርዝርዎን ለማዘጋጀት አካውንት አያስፈልግም። ሲልኩት የሞባይል ቁጥርዎን ያስገባሉ። ክፍያ የሚጠየቀው ስምምነቱ ሲጠናቀቅ ብቻ ነው፤ ከትዕዛዙ ዋጋ አነስተኛ መቶኛ። መጠኑ ወደፊት ይገለጻል።",
"No account yet? You enter your name and mobile number in the next step.": "አካውንት የለዎትም? በሚቀጥለው ደረጃ ስምዎንና የሞባይል ቁጥርዎን ያስገባሉ።",
"No buyer has asked to be verified yet.": "እስካሁን ለመረጋገጥ የጠየቀ ገዢ የለም።",
"No connection. Check the internet and try again.": "ግንኙነት የለም። ኢንተርኔቱን አረጋግጠው እንደገና ይሞክሩ።",
"No deliveries on the way right now.": "አሁን በመንገድ ላይ ያለ ማድረሻ የለም።",
