"Nothing is charged now. You pay as the payment terms of each order say, once the supplier confirms.": "አሁን ምንም አይከፈልም። አቅራቢው ካረጋገጠ በኋላ የእያንዳንዱ ትዕዛዝ የክፍያ ውል በሚለው መሠረት ይከፍላሉ።",
"Nothing is charged now. You pay once the supplier confirms, before the goods are dispatched.": "አሁን ምንም አይከፈልም። አቅራቢው ካረጋገጠ በኋላ፣ ዕቃዎቹ ከመላካቸው በፊት ይከፍላሉ።",
"Nothing is owed. Choose another offer for these lines under My requests.": "ምንም የሚከፈል ዕዳ የለም። ለእነዚህ መስመሮች ሌላ ዋጋ ቅናሽ በ«የእኔ ጥያቄዎች» ስር ይምረጡ።",
