"Nothing yet. Purchase Order / Sales Agreements and receipts appear here.": "እስካሁን ምንም የለም። የግዢ ትዕዛዝ / የሽያጭ ስምምነቶችና ደረሰኞች እዚህ ይታያሉ።",
"Nothing yet. Purchase orders, contracts and receipts appear here.": "እስካሁን ምንም የለም። የግዢ ትዕዛዞች፣ ውሎችና ደረሰኞች እዚህ ይታያሉ።",
