"Open requests in your categories are under Requests. Each line has the price filled in from your price list: choose the brand, check the price and the delivery, then press Send offer.": "በምድቦችዎ ያሉ ክፍት ጥያቄዎች በ«ጥያቄዎች» ስር ናቸው። እያንዳንዱ መስመር ከዋጋ ዝርዝርዎ የተሞላ ዋጋ አለው፤ ብራንዱን ይምረጡ፣ ዋጋውንና ርክክቡን ያረጋግጡ፣ ከዚያ «ዋጋ ላክ» ይጫኑ።",
