"Optional. Head office, stores or usual sites, so staff can suggest the delivery site next time. Private, never shown to anyone.": "አማራጭ። ዋና መሥሪያ ቤት፣ መጋዘኖች ወይም የተለመዱ የሥራ ቦታዎች፣ ሠራተኞች በሚቀጥለው ጊዜ የማድረሻ ቦታ እንዲጠቁሙ። ሚስጥራዊ ነው፤ ለማንም አይታይም።",
