"Orders on credit, and deposits whose balance is still open. Overdue ones first: call the buyer.": "በዱቤ ያሉ ትዕዛዞች እና ቀሪያቸው ገና ያልተከፈሉ ቅድመ ክፍያዎች። ጊዜያቸው ያለፈባቸው መጀመሪያ፦ ገዢውን ይደውሉ።",
