"Our service fee for this order:": "ለዚህ ትዕዛዝ የአገልግሎት ክፍያችን፦",
"Our team checks your request and sends it to suppliers, usually within one working hour. We text you when it has gone out; you see it under My requests.": "ቡድናችን ጥያቄዎን መርምሮ ለአቅራቢዎች ይልካል፤ ብዙውን ጊዜ በአንድ የሥራ ሰዓት ውስጥ። ሲላክ በጽሑፍ መልዕክት እናሳውቅዎታለን፤ በ«የእኔ ጥያቄዎች» ስርም ያዩታል።",
"Our team checks your request before it goes to suppliers, usually within one working hour. You get a text message when it has gone out.": "ጥያቄዎ ወደ አቅራቢዎች ከመሄዱ በፊት ቡድናችን ይመረምረዋል፤ ብዙውን ጊዜ በአንድ የሥራ ሰዓት ውስጥ። ሲላክ የጽሑፍ መልዕክት ይደርስዎታል።",
"Our team did not send this request to suppliers:": "ቡድናችን ይህን ጥያቄ ለአቅራቢዎች አልላከውም፦",
"Our team is checking them, usually within one working day. You can place orders meanwhile: the supplier holds them until you are verified.": "ቡድናችን እያረጋገጠ ነው፤ ብዙውን ጊዜ በአንድ የሥራ ቀን ውስጥ። እስከዚያው ትዕዛዝ ማስገባት ይችላሉ፤ እስኪረጋገጡ አቅራቢው ይይዘዋል።",
"Our team is typing in your list. It goes to suppliers soon; you get a text message.": "ቡድናችን ዝርዝርዎን እያስገባ ነው። በቅርቡ ወደ አቅራቢዎች ይሄዳል፤ የጽሑፍ መልዕክት ይደርስዎታል።",
"Our team reads your list, types the items in and sends the request to suppliers, usually within one working hour. You get a text message when it has gone out. You can also tick items above; they go in the same request.": "ቡድናችን ዝርዝርዎን አንብቦ ዕቃዎቹን ያስገባል፣ ጥያቄውንም ለአቅራቢዎች ይልካል፤ ብዙውን ጊዜ በአንድ የሥራ ሰዓት ውስጥ። ሲላክ የጽሑፍ መልዕክት ይደርስዎታል። ከላይ ዕቃዎችንም ምልክት ማድረግ ይችላሉ፤ በዚያው ጥያቄ ውስጥ ይሄዳሉ።",
"Our team types in your list and sends it to suppliers, usually within one working hour. We text you when it has gone out; you see it under My requests.": "ቡድናችን ዝርዝርዎን አስገብቶ ለአቅራቢዎች ይልካል፤ ብዙውን ጊዜ በአንድ የሥራ ሰዓት ውስጥ። ሲላክ በጽሑፍ መልዕክት እናሳውቅዎታለን፤ በ«የእኔ ጥያቄዎች» ስርም ያዩታል።",
"Our team verified you. You can place orders; orders on hold go to the suppliers now.": "ቡድናችን አረጋግጦዎታል። ትዕዛዞችን ማስገባት ይችላሉ፤ የተያዙ ትዕዛዞች አሁን ወደ አቅራቢዎች ይሄዳሉ።",
