"Outbox": "ወጪ መልዕክት",
"Outside Ethiopia": "ከኢትዮጵያ ውጭ",
"Outsourced procurement management for verified buyers, and outsourced marketing and sales management for verified suppliers.": "ለተረጋገጡ ገዢዎች የውጭ የግዥ አስተዳደር፣ ለተረጋገጡ አቅራቢዎች ደግሞ የውጭ የገበያና የሽያጭ አስተዳደር።",
