"Overview": "አጠቃላይ እይታ",
"Owner only.": "ለባለቤቱ ብቻ።",
"Owner only. Deletes every request, offer, order, message, problem, newsletter item, promotion, profile, task and supplier change, on every device. Tariffs, catalogue, brands and pictures stay.": "ለባለቤቱ ብቻ። እያንዳንዱን ጥያቄ፣ ዋጋ ማቅረቢያ፣ ትዕዛዝ፣ መልዕክት፣ ችግር፣ የዜና መጽሔት ጽሑፍ፣ ማስታወቂያ፣ መገለጫ፣ ተግባርና የአቅራቢ ለውጥ በሁሉም መሣሪያዎች ላይ ይሰርዛል። ታሪፎች፣ ካታሎግ፣ ብራንዶችና ምስሎች ይቀራሉ።",
"Owner only. Each staff member signs in with their own email and password. Tick the pages each person may open.": "ለባለቤቱ ብቻ። እያንዳንዱ ሠራተኛ በራሱ ኢሜይልና የይለፍ ቃል ይገባል። እያንዳንዱ ሰው ሊከፍታቸው የሚችላቸውን ገጾች ምልክት ያድርጉ።",
"Owner · sees everything": "ባለቤት · ሁሉንም ያያል",
"PO and delivery": "PO እና ማድረስ",
