"PO-BS-{1}-{2}-{3} deposit paid · ETB {4}. Prepare the goods.": "PO-BS-{1}-{2}-{3} ቅድመ ክፍያ ተከፍሏል · ETB {4}። ዕቃውን ያዘጋጁ።",
"PO-BS-{1}-{2}-{3} from Customer C-{4}. Confirm it within {5} hours, or decline it.": "PO-BS-{1}-{2}-{3} ከደንበኛ C-{4}። በ{5} ሰዓታት ውስጥ ያረጋግጡ ወይም ውድቅ ያድርጉ።",
"PO-BS-{1}-{2}-{3} from Sheba Builders PLC. Reconfirm price and stock.": "PO-BS-{1}-{2}-{3} ከSheba Builders PLC። ዋጋና ክምችትን ዳግም ያረጋግጡ።",
"PO-BS-{1}-{2}-{3} is confirmed by the supplier. It is binding now.": "PO-BS-{1}-{2}-{3} በአቅራቢው ተረጋግጧል። አሁን አስገዳጅ ነው።",
