"Pay-later terms (payment after delivery, credit, or a deposit with the balance later) are for verified buyers with a credit limit. Choose offers with full payment before dispatch, or get verified and ask us for credit.": "በኋላ የመክፈል ውሎች (ከርክክብ በኋላ ክፍያ፣ ዱቤ፣ ወይም ቅድመ ክፍያ ከቀሪው ጋር በኋላ) የዱቤ ገደብ ላላቸው የተረጋገጡ ገዢዎች ናቸው። ከመላኩ በፊት ሙሉ ክፍያ ያላቸውን ዋጋዎች ይምረጡ፣ ወይም ይረጋገጡና ዱቤ ይጠይቁን።",
"Pay-later terms (payment after delivery, credit, or a deposit with the balance later) need a verified account and a credit limit from Build Smartly. Ask for credit at checkout. A payment made after its due date carries a late charge, shown in your PO/SA, and pay-later is paused until an overdue payment is made.": "በኋላ የመክፈል ውሎች (ከርክክብ በኋላ ክፍያ፣ ዱቤ፣ ወይም ቅድመ ክፍያ ከቀሪው ጋር በኋላ) የተረጋገጠ መለያ እና ከቢልድ ስማርትሊ የዱቤ ገደብ ያስፈልጋቸዋል። ዱቤ በክፍያ ማጠናቀቂያው ላይ ይጠይቁ። ከመክፈያ ቀኑ በኋላ የሚፈጸም ክፍያ በግዢ ትዕዛዝ/ሽያጭ ስምምነትዎ ላይ የተገለጸ የዘገየ ክፍያ ቅጣት አለበት፣ እና ጊዜው ያለፈበት ክፍያ እስኪፈጸም ድረስ በኋላ መክፈል ይቆማል።",
"Pay-later terms need a verified account and a credit limit.": "በኋላ የመክፈል ውሎች የተረጋገጠ መለያ እና የዱቤ ገደብ ያስፈልጋቸዋል።",
