"Submit your licence and TIN and wait for verification. You can prepare your price list meanwhile.": "ፈቃድዎንና TINዎን አስገብተው ማረጋገጫውን ይጠብቁ። እስከዚያው የዋጋ ዝርዝርዎን ማዘጋጀት ይችላሉ።",
"Summary for a sales conversation": "ለሽያጭ ውይይት ማጠቃለያ",
