"Three new designs, boxes of {1} m². Samples at the shop; quotes through your request.": "ሦስት አዳዲስ ዲዛይኖች፣ በ{1} m² ካርቶን። ናሙናዎች በሱቁ ይገኛሉ፤ ዋጋ በጥያቄዎ በኩል።",
