"Type the quantity for each item and when you need it. Earliest date:": "ለእያንዳንዱ ዕቃ መጠኑንና የሚፈልጉበትን ቀን ይጻፉ። መጀመሪያ ሊሆን የሚችለው ቀን፦",
"Type the verification number printed at the bottom of the document, or scan its QR code.": "በሰነዱ ግርጌ የታተመውን የማረጋገጫ ቁጥር ይጻፉ፣ ወይም የQR ኮዱን ይቃኙ።",
"Type the {1}-digit code from the driver's delivery note.": "ከሾፌሩ የማድረሻ ማስታወሻ ባለ {1} አሃዝ ኮዱን ያስገቡ።",
"Type your message…": "መልዕክትዎን ይጻፉ…",
"Type your {1}-digit handover code to confirm.": "ለማረጋገጥ ባለ {1} አሃዝ የርክክብ ኮድዎን ያስገቡ።",
"Typed by the customer, not in the catalogue": "በደንበኛው የተጻፈ፣ በካታሎጉ ውስጥ የሌለ",
"Typed the buyer's handover code: goods handed over": "የገዢውን የማስረከቢያ ኮድ አስገብቷል፦ ዕቃዎቹ ተረክበዋል",
"Typed the delivery-note code: goods handed over": "የማስረከቢያ ደብተሩን ኮድ አስገብቷል፦ ዕቃዎቹ ተረክበዋል",
"Under Offers and orders, \"Waiting for your action\" shows what needs you: counter-offers, new PO/SAs to confirm, goods to mark ready and deliveries to dispatch. Each order page has the Purchase Order / Sales Agreement, the payment and the delivery.": "በ«ዋጋ ቅናሾችና ትዕዛዞች» ስር «እርምጃዎን የሚጠብቁ» እርስዎን የሚፈልጉትን ያሳያል፦ የዋጋ ጥያቄዎች፣ የሚረጋገጡ አዲስ የግ.ት/የሽ.ስዎች፣ ዝግጁ የሚባሉ ዕቃዎችና የሚላኩ ርክክቦች። እያንዳንዱ የትዕዛዝ ገጽ የግዢ ትዕዛዝ / የሽያጭ ስምምነቱን፣ ክፍያውንና ርክክቡን ይዟል።",
"Under Offers and orders, \"Waiting for your action\" shows what needs you: counter-offers, new orders to reconfirm, goods to mark ready and deliveries to dispatch. Each order page has the contract, the payment and the delivery.": "በ«ዋጋዎችና ትዕዛዞች» ስር «እርምጃዎን የሚጠብቁ» እርስዎን የሚፈልጉትን ያሳያል፦ የመልስ ዋጋዎች፣ እንደገና የሚረጋገጡ አዲስ ትዕዛዞች፣ ዝግጁ የሚባሉ እቃዎች እና የሚላኩ ርክክቦች። እያንዳንዱ የትዕዛዝ ገጽ ውሉን፣ ክፍያውንና ርክክቡን ይዟል።",
"Under Price list, tick the items you sell, type your price and press Save. Your quotes are filled in from it, and you can still change a price on each quote.": "በዋጋ ዝርዝር ስር የሚሸጡትን እቃዎች ምልክት ያድርጉ፣ ዋጋዎን ይጻፉና «አስቀምጥ» ይጫኑ። ዋጋ ማቅረቢያዎችዎ ከዚያ ይሞላሉ፤ በእያንዳንዱ ላይ ዋጋውን አሁንም መቀየር ይችላሉ።",
"Under each offer there is a box \"Your price per unit\" and a Counter button. The supplier accepts or declines; if accepted the order is issued at your price. The original offer stays valid meanwhile.": "በእያንዳንዱ ዋጋ ማቅረቢያ ስር «የእርስዎ ዋጋ በአንድ መለኪያ» የሚል ሳጥንና «ሌላ ዋጋ አቅርብ» ቁልፍ አለ። አቅራቢው ይቀበላል ወይም አይቀበልም፤ ከተቀበለ ትዕዛዙ በእርስዎ ዋጋ ይሰጣል። እስከዚያው የመጀመሪያው ዋጋ ማቅረቢያ ጸንቶ ይቆያል።",
"Unit": "መለኪያ",
"Unit price": "ነጠላ ዋጋ",
"Unit price (ETB)": "የአንዱ ዋጋ (ብር)",
"Update many at once": "ብዙዎችን በአንድ ጊዜ ያዘምኑ",
"Update prices from your phone, confirm unchanged prices in one action, or upload your whole list from Excel. You only receive requests for materials you sell, and you pay nothing until a deal completes.": "ዋጋዎችን ከስልክዎ ያዘምኑ፣ ያልተቀየሩ ዋጋዎችን በአንድ ጊዜ ያረጋግጡ፣ ወይም ሙሉ ዝርዝርዎን ከExcel ይጫኑ። የሚደርስዎ ለሚሸጧቸው ዕቃዎች የሚቀርብ ጥያቄ ብቻ ነው፤ ሽያጭ እስኪጠናቀቅ ምንም አይከፍሉም።",
"Upload a Word or PDF list": "የWord ወይም PDF ዝርዝር ይጫኑ",
"Upload photo": "ፎቶ ይጫኑ",
"Upload the business licence and TIN certificate under Settings → Documents. Staff review within {1} working days; until then quoting is locked.": "የንግድ ፈቃዱንና የTIN ሰርተፊኬቱን በማስተካከያዎች → ሰነዶች ስር ይጫኑ። ሠራተኞች በ{1} የሥራ ቀናት ውስጥ ይገመግማሉ፤ እስከዚያው ዋጋ ማቅረብ አይቻልም።",
"Upload your Excel or build it line by line. Multiple sites, multiple deliveries.": "Excelዎን ይጫኑ ወይም መስመር በመስመር ያዘጋጁ። ብዙ ሳይቶች፣ ብዙ ማድረሻዎች።",
