"Upload your price list": "የዋጋ ዝርዝርዎን ይጫኑ",
"Uploaded. A moderator checks it before it appears publicly.": "ተጭኗል። ለሕዝብ ከመታየቱ በፊት አወያዩ ያጣራዋል።",
